HOME_DIR = Path.home()

_RLWALK_SOUND_FILES = {
    "started": "rlwalk_started.wav",
    "error": "rlwalk_error.wav",
    "ended": "rlwalk_ended.wav",
}


def _rlwalk_sound_path(name: str) -> Path:
    return HOME_DIR / "sounds" / _RLWALK_SOUND_FILES[name]


def _sound_player_command():
    """Return a best-effort WAV player command, or None if unavailable."""
    candidates = (
        ("aplay", ["aplay", "-q"]),
    )
    for exe, cmd in candidates:
        found = shutil.which(exe)
        if found:
            return [found] + cmd[1:]
    return None


def _play_rlwalk_sound(name: str, *, enabled: bool, wait: bool = False) -> None:
    """Play one of the optional RLWalk status sounds.

    This is intentionally best-effort: a missing sound file or audio player
    should never prevent RLWalk from starting, stopping, or reporting errors.
    """
    logger.info(f"[RLWalk] sound event: {name!r}")
    if not enabled:
        logger.info(f"[RLWalk] not enabled: {name!r}")
        return
    try:
        path = _rlwalk_sound_path(name)
    except KeyError:
        logger.warning(f"[RLWalk] unknown sound event: {name!r}")
        return
    if not path.is_file():
        logger.warning(f"[RLWalk] sound file not found: {path}")
        return

    cmd = _sound_player_command()
    if not cmd:
        logger.warning("[RLWalk] no WAV playback command found")
        return

    argv = cmd + [str(path)]
    print(argv)
    try:
        if wait:
            subprocess.run(argv, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False, timeout=10.0)
        else:
            subprocess.Popen(argv, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, start_new_session=True)
    except Exception as exc:
        logger.warning(f"[RLWalk] failed to play sound {path}: {exc}")

def _policy_low_level_action_filter_enabled(policy) -> bool:
    """Return True when ONNX metadata says the policy was trained with
    the Disney-style low-level action path.

    Runtime should only send nonzero PolicyAction.duration for these policies.
    Old policies keep duration=0, which firmware treats as legacy immediate
    targets with no command FOH/LPF.
    """

    def nested(mapping, *keys):
        cur = mapping
        for key in keys:
            if not isinstance(cur, dict):
                return None
            cur = cur.get(key)
        return cur

    def enabled_from_value(value):
        b = _bool_or_none(value)
        if b is not None:
            return b
        if isinstance(value, dict):
            for key in ("enabled", "enable", "policy_action_filter", "action_filter", "foh_lpf"):
                b = _bool_or_none(value.get(key))
                if b is not None:
                    return b
            # Be permissive for exported configs that only store the parameters.
            b = _bool_or_none(value.get("first_order_hold"))
            if b is True:
                return True
            try:
                if float(value.get("motor_target_lpf_cutoff_hz", 0.0) or 0.0) > 0.0:
                    return True
            except Exception:
                pass
        return None

    cfg = getattr(policy, "config", {})
    info = getattr(policy, "info", {})

    candidates = [
        nested(cfg, "low_level_control"),
        nested(cfg, "disney_low_level"),
        nested(cfg, "actions", "low_level_control"),
        nested(cfg, "actions", "disney_low_level"),
        nested(info, "low_level_control"),
        nested(info, "LowLevelControl"),
        nested(info, ".LowLevelControl"),
        nested(info, "disney_low_level"),
        nested(info, "DisneyLowLevel"),
        nested(info, ".DisneyLowLevel"),
    ]
    for value in candidates:
        result = enabled_from_value(value)
        if result is not None:
            return bool(result)
    return False


def _policy_low_level_action_filter_params(policy) -> dict:
    """Return low-level action-filter parameters exported with the ONNX.

    This mirrors the metadata gate used by _policy_low_level_action_filter_enabled().
    The defaults match the firmware/PuddleDuck command path we are emulating:
    50 Hz policy targets reconstructed at a 600 Hz actuator-command loop with
    linear FOH and a 37.5 Hz first-order command low-pass.
    """

    def nested(mapping, *keys):
        cur = mapping
        for key in keys:
            if not isinstance(cur, dict):
                return None
            cur = cur.get(key)
        return cur

    def to_float(value, default):
        try:
            if value is None:
                return float(default)
            return float(value)
        except Exception:
            return float(default)

    def to_bool(value, default):
        b = _bool_or_none(value)
        if b is None:
            return bool(default)
        return bool(b)

    cfg = getattr(policy, "config", {})
    info = getattr(policy, "info", {})
    candidates = [
        nested(cfg, "low_level_control"),
        nested(cfg, "disney_low_level"),
        nested(cfg, "actions", "low_level_control"),
        nested(cfg, "actions", "disney_low_level"),
        nested(info, "low_level_control"),
        nested(info, "LowLevelControl"),
        nested(info, ".LowLevelControl"),
        nested(info, "disney_low_level"),
        nested(info, "DisneyLowLevel"),
        nested(info, ".DisneyLowLevel"),
    ]

    merged = {}
    for value in candidates:
        if isinstance(value, dict):
            merged.update(value)

    cutoff = merged.get("motor_target_lpf_cutoff_hz")
    if cutoff is None:
        cutoff = merged.get("target_lpf_cutoff_hz")
    if cutoff is None:
        cutoff = merged.get("command_lpf_cutoff_hz")
    if cutoff is None:
        cutoff = merged.get("cutoff_hz")

    update_hz = merged.get("actuator_update_hz")
    if update_hz is None:
        update_hz = merged.get("command_update_hz")
    if update_hz is None:
        update_hz = merged.get("low_level_update_hz")
    if update_hz is None:
        update_hz = merged.get("update_hz")

    first_order_hold = merged.get("first_order_hold")
    if first_order_hold is None:
        first_order_hold = merged.get("foh")

    return {
        "enabled": bool(_policy_low_level_action_filter_enabled(policy)),
        "first_order_hold": to_bool(first_order_hold, True),
        "motor_target_lpf_cutoff_hz": max(0.0, to_float(cutoff, 37.5)),
        "actuator_update_hz": max(1.0, to_float(update_hz, 600.0)),
    }

# Original PuddleDuck policy motor-family gains.
# Go1 joints use the original Go1 gains; UkiA1/A1 leg joints use the
# original A1 gains.  Non-Go/A1 joints are sent as NaN so firmware keeps the
# robot YAML/default gains for those actuators.
_ORIGINAL_POLICY_GO_GAINS = (10.0, 0.3)
_ORIGINAL_POLICY_A1_GAINS = (15.0, 0.6)
_ORIGINAL_POLICY_GAIN_CONFIG_KEY = "hardcode_original_policy_gains"


def _coerce_bool(value, *, default=False) -> bool:
    if value is None:
        return bool(default)
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    if isinstance(value, str):
        text = value.strip().lower()
        if text in ("1", "true", "yes", "y", "on"):
            return True
        if text in ("0", "false", "no", "n", "off", "none", "null", ""):
            return False
    raise ValueError(f"Expected boolean-like value, got {value!r}")


def _bool_or_none(value):
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    if isinstance(value, str):
        text = value.strip().lower()
        if text in ("1", "true", "yes", "y", "on"):
            return True
        if text in ("0", "false", "no", "n", "off", "none", "null", ""):
            return False
    return None


def _finite_vec3_from_attrs(obj, prefix: str):
    vals = []
    for axis in ("x", "y", "z"):
        try:
            v = float(getattr(obj, f"{prefix}_{axis}"))
        except Exception:
            return None
        if not math.isfinite(v):
            return None
        vals.append(v)
    return np.asarray(vals, dtype=np.float32)


def _imu_channels_description(has_gravity: bool, has_accel: bool) -> str:
    if has_gravity and has_accel:
        return "gravity and accelerometer"
    if has_gravity:
        return "gravity only"
    if has_accel:
        return "accelerometer only"
    return "neither gravity nor accelerometer"


