def _joint_leaf_name(joint_name) -> str:
    # Accept future joint names like robot/left_hip_yaw or policy.left_hip_yaw.
    name = str(joint_name).strip().lower()
    name = name.rsplit("/", 1)[-1]
    name = name.rsplit(".", 1)[-1]
    return name


def _original_policy_motor_family(joint_name) -> str | None:
    name = _joint_leaf_name(joint_name)

    # From the original PuddleDuck robot config:
    #   Go1:  hip_yaw, ankle, neck_pitch
    #   UkiA1: hip_roll, hip_pitch, knee
    if (
        name == "neck_pitch"
        or name.endswith("_neck_pitch")
        or name.endswith("hip_yaw")
        or name.endswith("ankle")
    ):
        return "go"

    if (
        name.endswith("hip_roll")
        or name.endswith("hip_pitch")
        or name.endswith("knee")
    ):
        return "a1"

    return None


def original_policy_gains_for_joints(joints):
    joint_kps = []
    joint_kds = []
    groups = {"go": [], "a1": [], "default": []}

    for joint in joints:
        family = _original_policy_motor_family(joint)
        if family == "go":
            kp, kd = _ORIGINAL_POLICY_GO_GAINS
            groups["go"].append(str(joint))
        elif family == "a1":
            kp, kd = _ORIGINAL_POLICY_A1_GAINS
            groups["a1"].append(str(joint))
        else:
            # Firmware treats NaN KP/KD entries as "do not override this joint".
            kp = math.nan
            kd = math.nan
            groups["default"].append(str(joint))

        joint_kps.append(kp)
        joint_kds.append(kd)

    return np.array(joint_kps, dtype=float), np.array(joint_kds, dtype=float), groups


