class PolicyBankInfer:
    """Small wrapper that switches between a general policy and a height-indexed bank.

    - `general` is used during height transitions
    - once the commanded height is stable for N steps, we switch to the closest bank policy

    This class intentionally exposes the *same* metadata as the general policy (via __getattr__)
    so downstream code (DuckDrive/DuckSense/RLWalk) remains unchanged.
    """

    def __init__(
        self,
        *,
        general,
        bank,
        stable_steps: int = 8,
        height_eps: float = 0.02,
        start_in_general: bool = True,
        debug_switch: bool = True,
    ):
        self.general = general
        self.bank = list(bank or [])
        self._stable_steps = max(1, int(stable_steps))
        self._height_eps = float(height_eps)
        self._start_in_general = bool(start_in_general)
        self._debug_switch = bool(debug_switch)

        self._log = logging.getLogger(__name__ + '.PolicyBank')

        self._active_kind = 'general' if self._start_in_general else 'bank'
        self._active_idx = None
        self._active = self.general if self._active_kind == 'general' else (self.bank[0] if self.bank else self.general)

        self._prev_height_cmd = None
        self._stable_count = 0

        self._validate_bank_metadata()

    def __getattr__(self, name):
        # Delegate *all* metadata to the general policy to guarantee consistency.
        return getattr(self.general, name)

    def _meta_sig(self, p):
        # Best-effort metadata signature used to validate bank compatibility.
        joints = tuple(getattr(p, 'joints', []) or [])
        cmd_size = int(getattr(p, 'command_size', 0) or 0)
        quat = bool(getattr(p, 'quat', False))
        contacts = bool(getattr(p, 'contacts', False)) if hasattr(p, 'contacts') else None
        cmd_index = getattr(p, 'command_index', None)
        cmd_index_items = tuple(sorted(cmd_index.items())) if isinstance(cmd_index, dict) else None

        # arrays
        def _maybe_arr(name):
            v = getattr(p, name, None)
            if v is None:
                return None
            try:
                import numpy as _np
                a = _np.array(v, dtype=float).ravel()
                return tuple(_np.round(a, 8))
            except Exception:
                return None

        kd = _maybe_arr('KD')
        ao = _maybe_arr('action_offset')
        return (joints, cmd_size, quat, contacts, cmd_index_items, kd, ao)

    def _validate_bank_metadata(self):
        if not self.bank:
            return
        ref = self._meta_sig(self.general)
        for i, p in enumerate(self.bank):
            sig = self._meta_sig(p)
            if sig != ref:
                raise ValueError(
                    f'Policy bank metadata mismatch at index {i}. '
                    'All bank policies must share the same metadata as the general policy.'
                )

    def _height_to_bank_index(self, h: float):
        n = len(self.bank)
        if n <= 0:
            return None
        h = float(max(-1.0, min(1.0, float(h))))
        if n == 1:
            return 0
        # Map [-1,1] -> [0, n-1] (inclusive), round-half-up.
        x = (h + 1.0) * (n - 1) / 2.0
        idx = int((x + 0.5) // 1)
        if idx < 0:
            idx = 0
        if idx > (n - 1):
            idx = n - 1
        return idx

    def _extract_height_cmd_from_obs(self, obs):
        try:
            cmd_index = getattr(self.general, 'command_index', None)
            if not isinstance(cmd_index, dict):
                return None
            idx_h = cmd_index.get('height', None)
            if idx_h is None:
                return None
            idx_h = int(idx_h)

            quat_len = 4 if bool(getattr(self.general, 'quat', False)) else 0
            cmd_size = int(getattr(self.general, 'command_size', 0) or 0)

            # RLWalk obs layout: gyro(3) + imu(3) + optional_quat + command
            cmd_start = 6 + quat_len
            cmd_end = cmd_start + cmd_size
            if cmd_end > len(obs):
                return None
            cmd = obs[cmd_start:cmd_end]
            if idx_h < 0 or idx_h >= len(cmd):
                return None
            return float(cmd[idx_h])
        except Exception:
            return None

    def _switch(self, *, kind: str, idx, height_cmd, reason: str):
        if kind == 'general':
            if self._active_kind != 'general':
                if self._debug_switch:
                    self._log.info(f'[PolicyBank] switch: bank[{self._active_idx}] -> general (h={height_cmd:.3f} reason={reason})')
            self._active_kind = 'general'
            self._active_idx = None
            self._active = self.general
            return

        # bank
        if idx is None or not self.bank:
            return
        if self._active_kind != 'bank' or self._active_idx != int(idx):
            if self._debug_switch:
                prev = 'general' if self._active_kind != 'bank' else f'bank[{self._active_idx}]'
                self._log.info(f'[PolicyBank] switch: {prev} -> bank[{int(idx)}] (h={height_cmd:.3f} reason={reason})')
        self._active_kind = 'bank'
        self._active_idx = int(idx)
        self._active = self.bank[int(idx)]

    def _update_active_from_obs(self, obs) -> None:
        h = self._extract_height_cmd_from_obs(obs)
        if h is None:
            return

        if self._prev_height_cmd is None:
            self._prev_height_cmd = h
            self._stable_count = 0
            # stay in starting policy for the first tick
            return

        delta = abs(float(h) - float(self._prev_height_cmd))
        self._prev_height_cmd = float(h)

        if delta > self._height_eps:
            self._stable_count = 0
            # transitioning: always use general
            self._switch(kind='general', idx=None, height_cmd=h, reason=f'dh={delta:.3f}')
            return

        # stable
        self._stable_count += 1
        if self._stable_count < self._stable_steps:
            return

        idx = self._height_to_bank_index(h)
        self._switch(kind='bank', idx=idx, height_cmd=h, reason=f'stable({self._stable_count})')

    def infer(self, obs):
        # Update active policy based on commanded height embedded in obs.
        self._update_active_from_obs(obs)
        return self._active.infer(obs)


def _resolve_relative(base: Path, p: str) -> str:
    pp = Path(p)
    if not pp.is_absolute():
        pp = (base.parent / pp).resolve()
    return str(pp)


def load_policy(path: str, *, verbose: bool = False, awd: bool = True):
    """Load either a single ONNX or a policy-bank YAML.

    YAML format (see train_policy_bank.py):
      general: [ONNX-general.onnx]
      policy_bank: [ONNX-0.onnx, ..., ONNX-15.onnx]
    """
    p = Path(path)
    suf = p.suffix.lower()

    if suf in ('.yml', '.yaml'):
        if yaml is None:
            raise RuntimeError('PyYAML is not installed; cannot load policy bank YAML.')
        data = yaml.safe_load(p.read_text()) or {}
        if not isinstance(data, dict):
            raise ValueError(f'Policy bank YAML root must be a mapping, got {type(data)}')

        general = data.get('general')
        bank = data.get('policy_bank')
        if general is None or bank is None:
            raise ValueError("Policy bank YAML must contain keys 'general' and 'policy_bank'.")

        # Allow general to be a string or a 1-element list
        if isinstance(general, (list, tuple)):
            if not general:
                raise ValueError("'general' list is empty")
            general = general[0]
        if not isinstance(general, str):
            raise ValueError(f"'general' must be a path string (or [path]), got {type(general)}")

        if not isinstance(bank, (list, tuple)) or not bank:
            raise ValueError("'policy_bank' must be a non-empty list of ONNX paths")

        general_path = _resolve_relative(p, general)
        bank_paths = [_resolve_relative(p, x) for x in bank]

        logger.info(f"[RLWalk] Loading policy bank YAML: {p}")
        logger.info(f"[RLWalk]  general: {general_path}")
        logger.info(f"[RLWalk]  bank size: {len(bank_paths)}")

        general_policy = OnnxInfer(general_path, verbose, awd=awd)
        bank_policies = [OnnxInfer(bp, verbose, awd=awd) for bp in bank_paths]
        return PolicyBankInfer(general=general_policy, bank=bank_policies, debug_switch=True)

    # Single ONNX
    return OnnxInfer(str(p), verbose, awd=awd)



class RLWalk:
    def __init__(
        self,
        onnx_model_path: str,
        serial_port: str = "/dev/puddleduck_ctrl",
        #control_freq: float = 50.0,
        action_scale=1.0,
        command_scale=[1.0, 1.0, 1.0],
        #vel_scale: float = 0.05,
        save_obs=False,
        replay_obs=None,
        replay_imu=None,
        replay_max=None,
        cutoff_frequency=None,
        allow_action=None,
        max_policy_steps=None,
        hardcode_original_policy_gains=None,
        verbose=False,
        duck_config: str = None,
        sounds: bool = False
    ):
        self.api = API(serial_port)
        self.sounds = bool(sounds)
        self._started_sound_played = False

        self.standing = False
        print("LOADING POLICY")

        self.policy = load_policy(onnx_model_path, verbose=verbose, awd=True)
        self.dt = self.policy.ctrl_dt
        self.tol = max(0.001, min(0.01, 0.1 * self.dt))
        self.policy_action_filter_params = _policy_low_level_action_filter_params(self.policy)
        self.policy_action_filter_enabled = bool(self.policy_action_filter_params.get("enabled", False))
        self.policy_action_duration_ms = int(round(self.dt * 1000.0)) if self.policy_action_filter_enabled else 0
        self.policy_action_filter_update_hz = float(self.policy_action_filter_params.get("actuator_update_hz", 600.0))
        self.policy_action_filter_cutoff_hz = float(self.policy_action_filter_params.get("motor_target_lpf_cutoff_hz", 37.5))
        self.policy_action_filter_foh = bool(self.policy_action_filter_params.get("first_order_hold", True))
        self.policy_action_filter_alpha = self._command_lpf_alpha(
            cutoff_hz=self.policy_action_filter_cutoff_hz,
            update_hz=self.policy_action_filter_update_hz,
        )
        logger.info(
            "[RLWalk] policy action FOH/LPF %s; PolicyAction.duration=%d ms, update_hz=%.1f, cutoff_hz=%.2f, alpha=%.6f, foh=%s",
            "enabled" if self.policy_action_filter_enabled else "disabled",
            self.policy_action_duration_ms,
            self.policy_action_filter_update_hz,
            self.policy_action_filter_cutoff_hz,
            self.policy_action_filter_alpha,
            self.policy_action_filter_foh,
        )

        self.joints = self.policy.joints
        self.vel_scale = self.policy.dof_vel_scale

        self.replay_imu = None
        self.replay_obs = None

        self.need_quat = self.policy.quat

        self.policy_imu_kind = "gravity" if self.policy.projected else "accelerometer"
        self._imu_contract_logged_ok = False
        self._imu_contract_failed = False
        logger.info(
            f"[RLWalk] policy IMU observation channel: {self.policy_imu_kind} "
        )

        self.num_dofs = len(self.joints)
        self.imitation_i = 0
        self.imitation_phase = np.array([0, 0])
        self.phase_frequency_factor = 1.0
        self.phase_frequency_factor_offset = (
            0
            #self.duck_config.phase_frequency_factor_offset
        )
        self.head_action_lp = None
        print(f"self.num_dofs: {self.num_dofs}")
        print(f"self.vel_scale: {self.vel_scale}")
        print(f"self.policy.KP: {self.policy.KP}")
        print(f"self.policy.KD: {self.policy.KD}")
        print(f"self.policy.action_offset: {self.policy.action_offset}")

        # We should read all these values from the onnx meta data now that it's there
        self.init_pos = np.array(self.policy.action_offset)

        # rlwalk_cfg = _load_rlwalk_config(duck_config)
        # if hardcode_original_policy_gains is None:
        #     hardcode_original_policy_gains = _coerce_bool(
        #         rlwalk_cfg.get(_ORIGINAL_POLICY_GAIN_CONFIG_KEY, False),
        #         default=False,
        #     )
        # else:
        #     hardcode_original_policy_gains = _coerce_bool(
        #         hardcode_original_policy_gains,
        #         default=False,
        #     )

        # By default, preserve the existing behavior and use ONNX metadata gains.
        self.joint_kps = np.array(self.policy.KP, dtype=float)
        self.joint_kds = np.array(self.policy.KD, dtype=float)
        self.gain_source = "policy metadata"
        self.hardcode_original_policy_gains = bool(hardcode_original_policy_gains)

        if self.hardcode_original_policy_gains:
            self.joint_kps, self.joint_kds, gain_groups = original_policy_gains_for_joints(self.joints)
            self.gain_source = "hardcoded original motor-family gains"
            logger.info(
                "[RLWalk] Ignoring policy KP/KD metadata; using original gains: "
                f"Go1 kp={_ORIGINAL_POLICY_GO_GAINS[0]} kd={_ORIGINAL_POLICY_GO_GAINS[1]}, "
                f"A1 kp={_ORIGINAL_POLICY_A1_GAINS[0]} kd={_ORIGINAL_POLICY_A1_GAINS[1]}"
            )
            logger.info(f"[RLWalk] Go1 gain joints: {gain_groups['go']}")
            logger.info(f"[RLWalk] A1 gain joints: {gain_groups['a1']}")
            if gain_groups["default"]:
                logger.info(
                    "[RLWalk] Non-Go/A1 joints will keep firmware/config defaults "
                    f"via NaN KP/KD entries: {gain_groups['default']}"
                )

        if len(self.joint_kps) != self.num_dofs or len(self.joint_kds) != self.num_dofs:
            raise ValueError(
                f"KP/KD length mismatch: num_dofs={self.num_dofs}, "
                f"len(KP)={len(self.joint_kps)}, len(KD)={len(self.joint_kds)}"
            )
        print(f"self.gain_source: {self.gain_source}")
        print(f"self.joint_kps sent: {self.joint_kps}")
        print(f"self.joint_kds sent: {self.joint_kds}")

        self.action_scale = action_scale
        self.command_scale = command_scale

        self.action_history_mode = self.policy.action_history_mode
        self.shallow_action_history = False
        if self.action_history_mode == "shallow":
            self.shallow_action_history = True

        self.last_action = np.zeros(self.num_dofs)
        self.last_last_action = np.zeros(self.num_dofs)
        self.last_last_last_action = np.zeros(self.num_dofs)

        # motor_targets is the raw target sent through PolicyAction.  For
        # policies trained with the Disney-style low-level command path, the
        # policy observation should instead see the *filtered command target*
        # that the firmware actuator loop is currently holding.  Keep those
        # states separate so the API still receives the raw policy target while
        # obs_motor_targets matches the applied/filtered command semantics.
        self.motor_targets = np.asarray(self.init_pos, dtype=np.float32).copy()
        self.obs_motor_targets = np.asarray(self.init_pos, dtype=np.float32).copy()
        self._policy_command_filter_state = np.asarray(self.init_pos, dtype=np.float32).copy()
        self._policy_command_filter_initialized = False
        self._policy_command_prev_setpoint = np.asarray(self.init_pos, dtype=np.float32).copy()
        self._policy_command_curr_setpoint = np.asarray(self.init_pos, dtype=np.float32).copy()

        self.commands = np.zeros(self.policy.command_size, dtype=np.float32)

        self.gyro_filter_alpha = 0.2
        self.filtered_gyro = np.zeros(3, dtype=np.float32)

        self.head_pitch_cmd = 0.0
        self.head_yaw_cmd   = 0.0
        self.head_roll_cmd  = 0.0

        # synthetic lateral velocity (from LB/RB)
        self.lin_vel_y_state = 0.0

        # synthetic height (from DPad DY)
        self.height_state = 0.0
        self.prev_dy      = 0.0

        # RLWalk observations are always captured by the command-line runtime.
        # The constructor flag remains useful for focused tests and library
        # callers, but normal ``python -m pd.runtime.RLWalk`` runs always pass
        # True below.
        self.save_obs = bool(save_obs)
        self.saved_pairs = []
        self.observation_started_ms = int(time.time() * 1000)
        self.observation_dir = Path(
            os.environ.get("PUDDLEDUCK_OBSERVATIONS_DIR", "~/observations")
        ).expanduser().resolve()
        policy_label = Path(str(onnx_model_path)).name
        policy_label = re.sub(r"[^A-Za-z0-9._-]+", "-", policy_label).strip("-._") or "policy"
        stamp_base = datetime.datetime.fromtimestamp(
            self.observation_started_ms / 1000.0,
            tz=datetime.timezone.utc,
        ).strftime("%Y%m%dT%H%M%S")
        stamp = f"{stamp_base}{self.observation_started_ms % 1000:03d}Z"
        self.observation_path = self.observation_dir / f"{stamp}_{policy_label}.pkl"
        self._observations_saved = False

        if replay_obs is not None:
            self.replay_obs = pickle.load(open(replay_obs, "rb"))
            self.replay_index = 0
            self.replay_max = len(self.replay_obs)
            if replay_max is not None:
                if replay_max < self.replay_max:
                    self.replay_max = replay_max
        elif replay_imu is not None:
            self.replay_imu = pickle.load(open(replay_imu, "rb"))
            self.replay_index = 0
            self.replay_max = len(self.replay_imu)
            if replay_max is not None:
                if replay_max < self.replay_max:
                    self.replay_max = replay_max

        self._last_obs_ts = None
        self.last_timestamp = 0

        self.allow_action = allow_action

        if max_policy_steps is None:
            self.max_policy_steps = None
        else:
            self.max_policy_steps = int(max_policy_steps)
            if self.max_policy_steps < 0:
                raise ValueError("max_policy_steps must be >= 0, or omit it to disable the limit")
        self.policy_steps_executed = 0
        self.policy_step_limit_stop_requested = False
        self._policy_stop_sent = False

        self.phase_gate_alpha = 0.0
        self.alpha_attack = 0.9
        self.alpha_decay = 0.1
        self.alpha_cmd_scale = 0.05
        self.alpha_rate_on = np.deg2rad(5.0)
        self.alpha_rate_full = np.deg2rad(30.0)
        self._phase_was_moving = False

        #self.action_msg = CommandProto.PolicyAction()
        logger.info(f"[RLWalk] ONNX providers: {self.policy.get_providers()}")

        # Shared sense logic (policy-rate)
        self.duck_config = duck_config
        self.duck_sense = DuckSense(policy=self.policy, config_yaml=duck_config)


    def _policy_step_limit_allows_next_step(self) -> bool:
        if self.max_policy_steps is None:
            return True
        return int(self.policy_steps_executed) < int(self.max_policy_steps)

    def _record_policy_step_executed(self) -> None:
        self.policy_steps_executed += 1
        if (
            self.max_policy_steps is not None
            and self.policy_steps_executed >= self.max_policy_steps
        ):
            self.policy_step_limit_stop_requested = True

    def _stop_policy_loop(self, reason: str = "") -> None:
        """Ask firmware to stop the policy observation/action loop.

        The protobuf API does not have a separate PolicyStop message. Sending a
        PolicyStart with an empty name and dt=0 makes firmware's
        isPolicyRunning() false, which stops periodic observation frames.
        """
        if self._policy_stop_sent:
            return
        msg = f"[RLWalk] stopping policy loop"
        if reason:
            msg += f": {reason}"
        logger.info(msg)
        try:
            self.api.policyStart("", dt=0.0)
        except Exception as exc:
            logger.warning(f"[RLWalk] failed to send policy stop request: {exc}")
        finally:
            self._policy_stop_sent = True

    def _check_hw_imu_contract(self, hwobs) -> bool:
        """Return False when hardware IMU channel cannot satisfy the policy."""
        if self.replay_imu is not None:
            return True

        hw_gravity = _finite_vec3_from_attrs(hwobs, "gravity")
        hw_accel = _finite_vec3_from_attrs(hwobs, "accel")
        has_gravity = hw_gravity is not None
        has_accel = hw_accel is not None
        reports = _imu_channels_description(has_gravity, has_accel)
        expected = str(self.policy_imu_kind or "unknown")

        ok = (expected == "gravity" and has_gravity) or (expected == "accelerometer" and has_accel)
        if ok:
            if not self._imu_contract_logged_ok:
                logger.info(
                    f"[RLWalk] IMU contract OK: policy expects {expected}; "
                    f"PuddleDuck reports {reports}; obs[3:6] will use {expected}."
                )
                self._imu_contract_logged_ok = True
            return True

        if not self._imu_contract_failed:
            logger.error(
                "[RLWalk] IMU OBSERVATION CONTRACT MISMATCH - refusing to run policy.\n"
                f"  Policy expects obs[3:6] = {expected}.\n"
                f"  PuddleDuck reports {reports}: "
                f"gravity_present={has_gravity}, accelerometer_present={has_accel}.\n"
                "  Use firmware/runtime that reports the same IMU channel the policy was trained on,\n"
                "  or run a policy trained/exported for the reported channel."
            )
            self._imu_contract_failed = True
        return False

    def select_policy_imu_vector(self, hwobs):
        """Return (hw_accel, hw_gravity, selected_imu, selected_kind)."""
        hw_gravity = _finite_vec3_from_attrs(hwobs, "gravity")
        hw_accel = _finite_vec3_from_attrs(hwobs, "accel")

        if self.replay_imu is not None:
            # The replay path replaces the whole IMU slice from a previous obs.
            # Use a finite placeholder here so hardware IMU absence does not
            # block replay; handle_observation overwrites it before inference.
            return hw_accel, hw_gravity, np.zeros(3, dtype=np.float32), "replay_imu"

        if not self._check_hw_imu_contract(hwobs):
            return hw_accel, hw_gravity, None, "mismatch"
        if self.policy_imu_kind == "gravity":
            return hw_accel, hw_gravity, hw_gravity, "gravity"
        if self.policy_imu_kind == "accelerometer":
            return hw_accel, hw_gravity, hw_accel, "accelerometer"

        # Explicit debug/legacy fallback when the check is disabled.
        if hw_gravity is not None:
            return hw_accel, hw_gravity, hw_gravity, "gravity"
        if hw_accel is not None:
            return hw_accel, hw_gravity, hw_accel, "accelerometer"
        return hw_accel, hw_gravity, None, "missing"

    def update_phase_gate_alpha(self, command, gyro=None):
        """Command-latched imitation phase gate.

        Gyro rate is intentionally ignored here. MJLab exposes phase through the
        command/recovery path, not directly from IMU motion; a gyro-triggered
        gate makes standing policies start stepping after small disturbances.
        """
        duck_drive = self.duck_drive

        def cmd_abs(idx):
            if idx is None:
                return 0.0
            try:
                return abs(float(command[int(idx)]))
            except Exception:
                return 0.0

        idx_lin_x = duck_drive.idx_lin_x
        idx_lin_y = duck_drive.idx_lin_y
        idx_yaw = duck_drive.idx_yaw
        idx_recover = duck_drive.idx_recover

        base_mag = max(cmd_abs(idx_lin_x), cmd_abs(idx_lin_y), cmd_abs(idx_yaw))
        recover_active = cmd_abs(idx_recover) > 0.5
        state_active = bool(duck_drive.any_state_active()) if duck_drive is not None else False

        cfg = self.policy.config
        cmd_cfg = cfg.get("command", {}) if isinstance(cfg, dict) else {}
        move_on = float(cmd_cfg.get("move_on_threshold", 0.08)) if isinstance(cmd_cfg, dict) else 0.08
        move_off = float(cmd_cfg.get("move_off_threshold", 0.04)) if isinstance(cmd_cfg, dict) else 0.04

        if self._phase_was_moving:
            self._phase_was_moving = not ((base_mag < move_off) and not recover_active)
        else:
            self._phase_was_moving = (base_mag > move_on) or recover_active

        self.phase_gate_alpha = 1.0 if self._phase_was_moving else 0.0
        return self.phase_gate_alpha

    # -------------------------------------------------------------------------
    # Replay/save compatibility helpers
    # -------------------------------------------------------------------------

    @staticmethod
    def _replay_as_1d_float_array(value, *, field_name: str) -> np.ndarray:
        try:
            arr = np.asarray(value, dtype=np.float32).reshape(-1)
        except Exception as e:
            raise TypeError(f"Replay field {field_name!r} is not numeric: {type(value).__name__}") from e
        if arr.size == 0:
            raise ValueError(f"Replay field {field_name!r} is empty")
        return arr

    def _replay_record_obs(self, record) -> np.ndarray:
        if isinstance(record, dict):
            for key in ("obs_hw", "obs", "obs_sim"):
                value = record.get(key, None)
                if value is not None:
                    return self._replay_as_1d_float_array(value, field_name=key)
            raise KeyError("Replay record has no 'obs_hw', 'obs', or 'obs_sim' field")
        return self._replay_as_1d_float_array(record, field_name="obs")

    def _replay_optional_array(self, record, *keys):
        if not isinstance(record, dict):
            return None
        for key in keys:
            value = record.get(key, None)
            if value is not None:
                return self._replay_as_1d_float_array(value, field_name=key)
        return None

    def _replay_command_slice(self) -> tuple[int, int]:
        quat_len = 4 if bool(getattr(self.policy, "quat", False)) else 0
        start = 6 + quat_len
        end = start + int(self.policy.command_size)
        return start, end

    def _replay_record_command(self, record, obs: np.ndarray | None = None) -> np.ndarray | None:
        cmd_size = int(self.policy.command_size)
        if cmd_size <= 0:
            return np.zeros(0, dtype=np.float32)

        raw = None
        if isinstance(record, dict):
            for key in ("command", "commands", "obs_cmd"):
                value = record.get(key, None)
                if value is not None:
                    raw = value
                    break

        if raw is None:
            if obs is None:
                obs = self._replay_record_obs(record)
            start, end = self._replay_command_slice()
            if obs.size < end:
                return None
            raw = obs[start:end]

        arr = self._replay_as_1d_float_array(raw, field_name="command")
        out = np.zeros(cmd_size, dtype=np.float32)
        n = min(cmd_size, arr.size)
        out[:n] = arr[:n]
        return out

    @staticmethod
    def _command_lpf_alpha(*, cutoff_hz: float, update_hz: float) -> float:
        cutoff_hz = float(cutoff_hz)
        update_hz = float(update_hz)
        if cutoff_hz <= 0.0 or update_hz <= 0.0:
            return 1.0
        dt = 1.0 / update_hz
        tau = 1.0 / (2.0 * math.pi * cutoff_hz)
        return float(dt / (tau + dt))

    def _reset_policy_command_filter_mirror(self, target) -> np.ndarray:
        target = np.asarray(target, dtype=np.float32).reshape(self.num_dofs)
        self._policy_command_filter_state = target.copy()
        self._policy_command_filter_initialized = True
        self._policy_command_prev_setpoint = target.copy()
        self._policy_command_curr_setpoint = target.copy()
        self.obs_motor_targets = target.copy()
        return target.copy()

    def _advance_policy_command_filter_mirror(self, raw_target) -> np.ndarray:
        """Mirror the firmware policy command FOH+LPF at policy-tick cadence.

        The firmware receives raw policy targets at 50 Hz, reconstructs the
        command at the actuator-update rate with linear FOH, then applies the
        command LPF.  The policy observation's motor_targets block should reflect
        that filtered command target, not the new raw target we just sent.

        This function advances the mirror by one policy interval after sending
        raw_target and returns the command target that should be visible in the
        *next* policy observation.
        """
        raw = np.asarray(raw_target, dtype=np.float32).reshape(self.num_dofs)

        if not bool(getattr(self, "policy_action_filter_enabled", False)):
            return self._reset_policy_command_filter_mirror(raw)

        if not self._policy_command_filter_initialized:
            # First policy packet starts from the currently observed/held target.
            self._reset_policy_command_filter_mirror(self.obs_motor_targets)

        prev = np.asarray(self._policy_command_curr_setpoint, dtype=np.float32).copy()
        curr = raw.copy()
        lpf = np.asarray(self._policy_command_filter_state, dtype=np.float32).copy()
        alpha = float(getattr(self, "policy_action_filter_alpha", 1.0))
        if not np.isfinite(alpha) or alpha < 0.0:
            alpha = 1.0
        if alpha > 1.0:
            alpha = 1.0

        duration_s = max(0.0, float(getattr(self, "policy_action_duration_ms", 0)) / 1000.0)
        update_hz = max(1.0, float(getattr(self, "policy_action_filter_update_hz", 600.0)))
        n_substeps = max(1, int(round(duration_s * update_hz)))

        if not bool(getattr(self, "policy_action_filter_foh", True)):
            for _ in range(n_substeps):
                lpf = (1.0 - alpha) * lpf + alpha * curr
        else:
            for k in range(1, n_substeps + 1):
                u = float(k) / float(n_substeps)
                foh = prev + (curr - prev) * u
                lpf = (1.0 - alpha) * lpf + alpha * foh

        lpf = lpf.astype(np.float32, copy=False)
        self._policy_command_prev_setpoint = prev.astype(np.float32, copy=False)
        self._policy_command_curr_setpoint = curr.astype(np.float32, copy=False)
        self._policy_command_filter_state = lpf.copy()
        self._policy_command_filter_initialized = True
        self.obs_motor_targets = lpf.copy()
        return lpf.copy()

    def handle_observation(self, hwobs):
        now = time.time()
        if self._last_obs_ts is not None:
            elapsed = now - self._last_obs_ts
            self._last_obs_ts = now
            # allow a small epsilon before issuing warning
            if abs(elapsed - self.dt) > self.tol:
                logger.warning(f"[RLWalk] [Warning] expected dt={self.dt:.4f}s but got {elapsed:.4f}s num={hwobs.num} timestamp={hwobs.timestamp} diff={hwobs.timestamp-self.last_timestamp}")
                # drop this frame / signal overrun
                #self.last_timestamp = hwobs.timestamp
                #return False
            self.last_timestamp = hwobs.timestamp
        self._last_obs_ts = now

        if not self._policy_step_limit_allows_next_step():
            self.policy_step_limit_stop_requested = True
            logger.warning(
                f"[RLWalk] max_policy_steps={self.max_policy_steps} reached before "
                f"processing observation num={getattr(hwobs, 'num', 'NA')}"
            )
            return False

        policy_step_index = int(self.policy_steps_executed)

        hw_commands = np.array([
            hwobs.cmd_lin_vel_x,
            hwobs.cmd_lin_vel_y,
            hwobs.cmd_ang_vel,
            0 # no hw height command yet
        ])

        self.imitation_i += 1.0 * self.phase_frequency_factor
        self.imitation_i = (
            self.imitation_i % self.policy.nb_steps_in_period
        )
        self.imitation_phase = np.array(
            [
                np.cos(
                    self.imitation_i / self.policy.nb_steps_in_period * 2 * np.pi
                ),
                np.sin(
                    self.imitation_i / self.policy.nb_steps_in_period * 2 * np.pi
                ),
            ]
        )
        dof_pos = np.array(hwobs.joint_angles)
        dof_vel = np.array(hwobs.joint_vel)
        # dof_pos = np.array(np.around(hwobs.joint_angles, 5))
        # dof_vel = np.array(np.around(hwobs.joint_vel, 5))

        hw_gyro = np.array([hwobs.gyro_x, hwobs.gyro_y, hwobs.gyro_z], dtype=np.float32)
        hw_accel, hw_gravity, selected_imu, selected_imu_kind = self.select_policy_imu_vector(hwobs)
        if selected_imu is None:
            self._stop_policy_loop("IMU observation contract mismatch")
            return False
        hw_quat = np.array([hwobs.quat_w, hwobs.quat_x, hwobs.quat_y, hwobs.quat_z], dtype=np.float32)

        obs_sim = None
        action_sim = None
        dof_pos_sim = None
        motor_target_sim = None

        gyro = hw_gyro
        imu = selected_imu
        imu_kind = selected_imu_kind
        quat = hw_quat
        if self.replay_imu is not None:
            if self.replay_index < self.replay_max:
                entry = self.replay_imu[self.replay_index]
                obs_imu_sim = self._replay_record_obs(entry)
                gyro = obs_imu_sim[:3]
                imu = obs_imu_sim[3:6]
                if self.need_quat:
                    quat = obs_imu_sim[6:10]
                imu_kind = "replay_imu"

                self.replay_index = self.replay_index + 1
        elif self.replay_obs is not None:
            # If we are replaying obs then replace the hardware obs with the pickled obs
            if self.replay_index < self.replay_max:
                entry = self.replay_obs[self.replay_index]
                obs_sim = self._replay_record_obs(entry)
                action_sim = self._replay_optional_array(entry, 'action', 'action_sim', 'action_hw')
                motor_target_sim = self._replay_optional_array(entry, 'motor', 'motor_sim')
                dof_pos_sim = self._replay_optional_array(entry, 'dof_pos', 'dof_pos_sim')

                # Copy commands from an explicit field when available; otherwise
                # slice them out of the saved observation layout.
                replay_cmd = self._replay_record_command(entry, obs_sim)
                if replay_cmd is not None:
                    ncmd = min(len(self.commands), len(replay_cmd))
                    self.commands[:ncmd] = replay_cmd[:ncmd]

                self.replay_index = self.replay_index + 1
            else:
                logger.info("End of pickled observations")
                return False

        optional_quat = quat if self.need_quat else np.array([])
        obs_cmd = np.array(self.commands, dtype=np.float32)
        # Apply DuckSense overrides (e.g., walk-in-place recovery) using IMU-only signals.
        if self.duck_sense is not None:
            obs_cmd = self.duck_sense.apply_walk_in_place(
                obs_cmd,
                gyro=(float(gyro[0]), float(gyro[1]), float(gyro[2])),
                quat_wxyz=(float(quat[0]), float(quat[1]), float(quat[2]), float(quat[3])),
                v_loc=None,
            )

        # DuckDrive may also request walk-in-place (e.g. manual "march" state).
        if getattr(self, "duck_drive", None) is not None:
            obs_cmd = self.duck_drive.apply_walk_in_place(obs_cmd)

        alpha = self.update_phase_gate_alpha(obs_cmd, gyro)
        speed = float(getattr(getattr(self, "duck_drive", None), "imitation_phase_speed", 1.0))
        gated_phase = self.imitation_phase * alpha * speed

        # This is the motor-target vector that is present inside obs_hw[t].
        # For FOH/LPF-trained policies, this must be the mirrored filtered
        # command target currently held by the firmware actuator loop, not the
        # raw policy target sent at the previous tick.
        obs_motor_targets_before_policy = np.asarray(self.obs_motor_targets, dtype=np.float32).copy()

        action_history_obs = [self.last_action]
        if not self.shallow_action_history:
            action_history_obs.extend([self.last_last_action, self.last_last_last_action])

        obs_hw = np.concatenate(
            [
                gyro,
                imu,
                optional_quat,
                obs_cmd,
                dof_pos - self.init_pos,
                dof_vel * self.vel_scale,
                *action_history_obs,
                obs_motor_targets_before_policy,
                gated_phase,
            ]
        )
        # Raw policy output, before any runtime post-processing.  This is the
        # quantity that should match MuJoCo's motor_raw_policy_target formula:
        #   action_offset + action_raw_policy * action_scale
        action_raw_policy = self.policy.infer(obs_hw)
        action = action_raw_policy.copy()

        if self.head_action_lp is None:
            self.head_action_lp = action.copy()

        dd = getattr(self, "duck_drive", None)
        idx_hp = getattr(dd, "idx_head_pitch", None) if dd is not None else None
        idx_hy = getattr(dd, "idx_head_yaw", None) if dd is not None else None
        idx_hr = getattr(dd, "idx_head_roll", None) if dd is not None else None
        head_cmd_pitch = obs_cmd[int(idx_hp)] if (idx_hp is not None and int(idx_hp) < len(obs_cmd)) else (obs_cmd[5] if len(obs_cmd) > 5 else 0.0)
        head_cmd_yaw   = obs_cmd[int(idx_hy)] if (idx_hy is not None and int(idx_hy) < len(obs_cmd)) else (obs_cmd[6] if len(obs_cmd) > 6 else 0.0)
        head_cmd_roll  = obs_cmd[int(idx_hr)] if (idx_hr is not None and int(idx_hr) < len(obs_cmd)) else (obs_cmd[7] if len(obs_cmd) > 7 else 0.0)
        head_cmd_mag   = max(
            abs(head_cmd_pitch),
            abs(head_cmd_yaw),
            abs(head_cmd_roll),
        )

        # forward velocity command (controls gait / bob)
        lin_vel_cmd = obs_cmd[0] if len(obs_cmd) > 0 else 0.0

        CMD_THRESH   = 0.05     # head joystick “active”
        WALK_THRESH  = 0.05     # walking vs standing

        # yaw/roll filter gains
        ALPHA_IDLE_YR   = 0.02  # heavy low-pass
        ALPHA_ACTIVE_YR = 0.3   # lighter low-pass

        # pitch/neck filter gains
        ALPHA_IDLE_P    = 0.05  # when standing & no head cmd
        ALPHA_ACTIVE_P  = 0.4   # when walking or head cmd

        DEAD_BAND = 0.01        # only for “idle” case

        head_aim_active = head_cmd_mag >= CMD_THRESH
        gait_active     = abs(lin_vel_cmd) >= WALK_THRESH

        # self.last_last_last_action = self.last_last_action.copy()
        # self.last_last_action = self.last_action.copy()
        # self.last_action = action.copy()

        for jname in ("head_yaw", "head_roll", "head_pitch", "neck_pitch"):
            if jname not in self.joints:
                continue

            idx  = self.joints.index(jname)
            prev = self.head_action_lp[idx]
            raw  = action[idx]

            # --- choose alpha / deadband per joint type ---
            if jname in ("head_yaw", "head_roll"):
                # yaw/roll: only care about joystick head aim
                if head_aim_active:
                    alpha = ALPHA_ACTIVE_YR
                    local_dead = 0.0
                else:
                    alpha = ALPHA_IDLE_YR
                    local_dead = DEAD_BAND
            else:
                # pitch / neck_pitch:
                # standing & no head cmd -> idle smoothing
                # walking OR head cmd -> let bob through
                if (not gait_active) and (not head_aim_active):
                    alpha = ALPHA_IDLE_P
                    local_dead = DEAD_BAND
                else:
                    alpha = ALPHA_ACTIVE_P
                    local_dead = 0.0

            # exponential low-pass
            filt = prev * (1.0 - alpha) + raw * alpha

            # apply deadband only in "idle" mode
            if local_dead > 0.0 and abs(filt) < local_dead:
                filt = 0.0

            self.head_action_lp[idx] = filt
            action[idx] = filt

        # Update action history
        self.last_last_last_action = self.last_last_action.copy()
        self.last_last_action = self.last_action.copy()
        self.last_action = action.copy()

        # Compute target bookkeeping using the same raw/applied split as MuJoCo.
        # Raw target: direct policy output mapped through action offset/scale.
        # Applied HW target: target after runtime post-processing such as the
        # head/neck low-pass/deadband above.
        motor_raw_policy_target_hw = (
            self.init_pos + action_raw_policy.astype(np.float32, copy=False) * self.action_scale
        ).astype(np.float32, copy=False)
        motor_applied_target_hw = (
            self.init_pos + action.astype(np.float32, copy=False) * self.action_scale
        ).astype(np.float32, copy=False)
        motor_targets_hw = motor_applied_target_hw

        if motor_target_sim is None:
            self.motor_targets = motor_applied_target_hw
        else:
            # In replay mode this is the actual raw target sent to firmware. Keep
            # motor_hw as the locally-computed hardware target, and save the
            # mirrored filtered/applied target separately.
            self.motor_targets = motor_target_sim
        motor_sent_target = np.asarray(self.motor_targets, dtype=np.float32).copy()
        motor_command_target_next = self._advance_policy_command_filter_mirror(motor_sent_target)

        if self.save_obs:
            self.saved_pairs.append({
                'recorded_wall_ms': int(time.time() * 1000),
                'recorded_monotonic_s': float(time.monotonic()),
                'policy_step': policy_step_index,
                'policy_name': str(getattr(self.policy, 'name', '') or Path(str(self.observation_path)).stem),
                'joint_names': list(self.joints),
                'obs_num': int(getattr(hwobs, 'num', 0)),
                'obs_timestamp_ms': int(getattr(hwobs, 'timestamp', 0)),
                'obs_sim': None if obs_sim is None else obs_sim.copy(),
                'obs_hw':  obs_hw.copy(),
                # Save explicit signal slices so downstream replay tools do not
                # have to reverse-engineer command_size / quat layout.
                'command': obs_cmd.copy(),
                'command_names': list(getattr(self.policy, 'commands', [])),
                'gyro': np.asarray(gyro, dtype=np.float32).copy(),
                'accel': None if hw_accel is None else np.asarray(hw_accel, dtype=np.float32).copy(),
                'gravity': None if hw_gravity is None else np.asarray(hw_gravity, dtype=np.float32).copy(),
                'imu': np.asarray(imu, dtype=np.float32).copy(),
                'imu_kind': str(imu_kind),
                'hw_reports_accel': bool(hw_accel is not None),
                'hw_reports_gravity': bool(hw_gravity is not None),
                'quat': np.asarray(quat, dtype=np.float32).copy(),
                'action_sim':  None if action_sim is None else action_sim.copy(),
                # Backward-compatible action_hw is the action actually used to
                # compute the local hardware target after any runtime filters.
                'action_hw':  action.copy(),
                'action': action.copy(),
                'action_raw_policy_hw': action_raw_policy.copy(),
                'action_applied_hw': action.copy(),
                'motor_sim':  None if motor_target_sim is None else motor_target_sim.copy(),
                # Backward-compatible motor_hw remains the locally-computed
                # hardware target after action filters.
                'motor_hw':  motor_targets_hw.copy(),
                'motor_raw_policy_target_hw': motor_raw_policy_target_hw.copy(),
                'motor_applied_target_hw': motor_applied_target_hw.copy(),
                # Unqualified names match MuJoCo/compare_saved_obs semantics.
                # motor_sent_target is the raw target handed to PolicyAction.
                # motor_applied_target/motor are the mirrored command target after
                # the firmware FOH+LPF path for policies trained with that path.
                'motor_raw_policy_target': motor_raw_policy_target_hw.copy(),
                'motor_applied_target': motor_command_target_next.copy(),
                'motor': motor_command_target_next.copy(),
                'motor_sent_target': motor_sent_target.copy(),
                'motor_command_target_mirror': motor_command_target_next.copy(),
                'motor_command_target_before_policy': obs_motor_targets_before_policy.copy(),
                'desired_motor': motor_raw_policy_target_hw.copy(),
                'obs_motor_targets': obs_motor_targets_before_policy.copy(),
                'obs_motor_targets_before_policy': obs_motor_targets_before_policy.copy(),
                'obs_motor_targets_next': motor_command_target_next.copy(),
                'policy_action_filter_update_hz': float(self.policy_action_filter_update_hz),
                'policy_action_filter_cutoff_hz': float(self.policy_action_filter_cutoff_hz),
                'policy_action_filter_alpha': float(self.policy_action_filter_alpha),
                'dof_pos': dof_pos.copy(),
                'dof_pos_sim': None if dof_pos_sim is None else dof_pos_sim.copy(),
                'init_pos':  self.init_pos.copy(),
                'policy_action_filter_enabled': bool(self.policy_action_filter_enabled),
                'policy_action_duration_ms': int(self.policy_action_duration_ms),
            })

        if self.allow_action:
            self.api.policyAction(
                "default",
                joint_radians=self.motor_targets,
                joint_kps=self.joint_kps,
                joint_kds=self.joint_kds,
                duration=self.policy_action_duration_ms)

        self._record_policy_step_executed()
        return True

    def moveToSimStartPosition(self):
        if self.replay_obs is None:
            return
        if self.replay_index < self.replay_max:
            entry = self.replay_obs[self.replay_index]
            dof_pos_sim = self._replay_optional_array(entry, 'dof_pos', 'dof_pos_sim')
            if dof_pos_sim is None:
                return
            if self.allow_action:
                print(f"dof_pos_sim: {dof_pos_sim}")
                self.api.policyAction(
                    "default",
                    joint_radians=dof_pos_sim)

    def _play_sound(self, name: str, *, wait: bool = False) -> None:
        _play_rlwalk_sound(name, enabled=self.sounds, wait=wait)

    def _play_started_sound_once(self) -> None:
        if self._started_sound_played:
            return
        self._started_sound_played = True
        self._play_sound("started", wait=False)

    def _save_observations(self) -> None:
        if not self.save_obs or self._observations_saved:
            return
        self._observations_saved = True
        self.observation_dir.mkdir(parents=True, exist_ok=True)
        tmp = self.observation_path.with_name(
            f".{self.observation_path.name}.tmp-{os.getpid()}-{time.time_ns()}"
        )
        try:
            with tmp.open("wb") as stream:
                pickle.dump(self.saved_pairs, stream, protocol=pickle.HIGHEST_PROTOCOL)
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(tmp, self.observation_path)
            try:
                os.chmod(self.observation_path, 0o644)
            except OSError:
                pass
            print(
                f"[RLWalk] saved {len(self.saved_pairs)} observation records to "
                f"{self.observation_path}",
                flush=True,
            )
        finally:
            try:
                tmp.unlink()
            except FileNotFoundError:
                pass

    def run(self):
        PuddleJoy.load_default_controller_definitions()
        controllers = PuddleJoy.discover()
        if not controllers:
            logger.error("No controllers found. Exiting.")
            exit(1)

        # Normalize raw controller input to [-1, 1]
        for c in controllers:
            c.set_scale(-1.0, 1.0)

        # Shared high-rate drive logic
        self.duck_drive = DuckDrive(
            policy=self.policy,
            controllers=controllers,
            commands=self.commands,
            config_yaml=self.duck_config,
            engaged=False
        )


        try:
            logger.info("[RLWalk] starting main loop...")
            if self.max_policy_steps is not None:
                logger.warning(
                    f"[RLWalk] max_policy_steps={self.max_policy_steps}: "
                    "will stop immediately after that many policy inferences/actions"
                )
            self._policy_stop_sent = False
            self.api.policyStart("default", dt=self.dt)
            self._play_started_sound_once()

            lastObsTime = time.time()
            started = False  # Wait for user to press 'Power'
            running = True
            counter = 0

            while running:
                now = time.time()

                # Update the command vector from the controller(s)
                self.duck_drive.update(now)

                st = self.duck_drive.status()
                active = st.get("active", "")
                strafe_src = st.get("strafe", "")

                cmd_string = " ".join("{:0.4f}".format(float(x)) for x in self.commands)
                sys.stdout.write(
                    f"\r[{counter}][{strafe_src}] {active}:{cmd_string}                                          "
                )
                sys.stdout.flush()
                counter += 1

                # Button handling (pressed events)
                for b in self.duck_drive.pop_pressed():
                    print(f"button: {b}")
                    if b == "Select":
                        print("Select")
                        # if not started:
                        #     self.moveToSimStartPosition()
                    elif b == "Power" or b == "start":
                        if started:
                            running = False
                            print("ENDING POLICY")
                            self.duck_drive.disengage(reset_commands=True)
                            self._stop_policy_loop("Power button pressed while running")
                            break
                        print("STARTING POLICY")
                        started = True
                        started = self.duck_drive.engage(now, settle_s=0.10)
                    elif b in ("LS_B", "RS_B", "A", "X", "Y", "LB", "RB"):
                        print(b)

                # Receive observations at fixed DT interval.
                msg_type, msg = self.api.receive(blocking=True)

                if msg_type is None:
                    now2 = time.time()
                    if self._last_obs_ts is not None:
                        lastObsTime = self._last_obs_ts
                    elapsed = now2 - lastObsTime
                    if elapsed > self.dt * 2:
                        logger.info("Not receiving observations")
                        break
                    continue

                if msg_type == "obs":
                    if not self._check_hw_imu_contract(msg):
                        self.duck_drive.disengage(reset_commands=True)
                        self._stop_policy_loop("IMU observation contract mismatch")
                        running = False
                        break
                    if started:
                        if not self.handle_observation(msg):
                            break
                        if self.policy_step_limit_stop_requested:
                            logger.warning(
                                f"[RLWalk] reached max_policy_steps={self.max_policy_steps}; "
                                "disengaging and stopping policy loop"
                            )
                            self.duck_drive.disengage(reset_commands=True)
                            self._stop_policy_loop("max_policy_steps reached")
                            running = False
                            break
                else:
                    logger.warning(f"[warn] unhandled command: {msg_type}")

        except KeyboardInterrupt:
            pass
        finally:
            self._stop_policy_loop("RLWalk.run exiting")
            self._save_observations()

if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser()
    parser.add_argument("--onnx_model_path", type=str, required=True, help="ONNX policy (*.onnx) or policy bank YAML (*.yml/*.yaml)")
    parser.add_argument(
        "--duck_control",
        type=str,
        required=False,
        default="duck_control.yaml",
        help="YAML config for DuckDrive/DuckSense (optional).",
    )
    parser.add_argument("--action_scale", type=float, default=0.25)
    parser.add_argument("--command_scale", nargs=3, type=float, default=[1.0, 1.0, 1.0], help="Command scale [1.0 1.0 1.0] (range 0.0 - 1.0)")
    #parser.add_argument("--vel_scale", type=float, default=0.05)
    #parser.add_argument("--control_freq", type=float, default=50)
    parser.add_argument(
        "--allow_action",
        action="store_true",
        help="enable policy actions",
    )
    parser.add_argument(
        "--max_policy_steps", "--policy_steps",
        dest="max_policy_steps",
        type=int,
        default=None,
        help=(
            "Maximum number of started policy observations to process before "
            "automatically stopping the firmware policy loop. Omit for no cap; "
            "0 starts the observation loop but sends no policy action."
        ),
    )
    parser.add_argument(
        "--hardcode_original_policy_gains",
        action="store_true",
        default=None,
        help=(
            "Ignore ONNX policy KP/KD metadata and send original PuddleDuck "
            "motor-family gains instead: Go1 kp=10 kd=0.3, A1 kp=15 kd=0.6. "
            "Non-Go/A1 joints keep firmware/config defaults."
        ),
    )
    parser.add_argument(
        "--replay_obs",
        type=str,
        required=False,
        default=None,
        help="replay the observations from a previous run (can be from the robot or from mujoco)",
    )
    parser.add_argument(
        "--replay_imu",
        type=str,
        required=False,
        default=None,
        help="replay the imu observations from a previous run (can be from the robot or from mujoco)",
    )
    parser.add_argument(
        "--replay_max",
        type=int,
        required=False,
        default=None,
        help="replay maximum number of observations",
    )
    parser.add_argument("--cutoff_frequency", type=float, default=None)
    parser.add_argument(
        "--sounds",
        action="store_true",
        help=(
            "Play RLWalk status WAVs from $HOME/sounds/: "
            "rlwalk_started.wav after startup, rlwalk_error.wav on startup/runtime error, "
            "and rlwalk_ended.wav on a clean exit."
        ),
    )
    parser.add_argument(
        "-v", "--verbose",
        action="store_true",
        help="Verbose output"
    )
    try:
        args = parser.parse_args()
    except SystemExit as exc:
        # argparse exits before args exists. Honor --sounds for invocation/startup errors.
        code = exc.code if isinstance(exc.code, int) else (0 if exc.code is None else 1)
        if int(code) != 0 and "--sounds" in sys.argv[1:]:
            _play_rlwalk_sound("error", enabled=True, wait=True)
        raise

    args.action_scale = max(0.0, min(1.0, args.action_scale))
    args.command_scale = [max(0.0, min(1.0, c)) for c in args.command_scale]

    try:
        rl_walk = RLWalk(
            args.onnx_model_path,
            #control_freq=args.control_freq,
            action_scale=args.action_scale,
            command_scale=args.command_scale,
            #vel_scale=args.vel_scale,
            save_obs=True,
            replay_obs=args.replay_obs,
            replay_imu=args.replay_imu,
            replay_max=args.replay_max,
            cutoff_frequency=args.cutoff_frequency,
            allow_action=args.allow_action,
            max_policy_steps=args.max_policy_steps,
            hardcode_original_policy_gains=args.hardcode_original_policy_gains,
            verbose=args.verbose,
            duck_config=args.duck_control,
            sounds=args.sounds,
        )
        logger.info("Done instantiating RLWalk")
        rl_walk.run()
    except SystemExit as exc:
        code = exc.code if isinstance(exc.code, int) else (0 if exc.code is None else 1)
        if int(code) == 0:
            _play_rlwalk_sound("ended", enabled=args.sounds, wait=True)
        else:
            _play_rlwalk_sound("error", enabled=args.sounds, wait=True)
        raise
    except Exception:
        logger.exception("[RLWalk] failed")
        _play_rlwalk_sound("error", enabled=args.sounds, wait=True)
        sys.exit(1)
    else:
        _play_rlwalk_sound("ended", enabled=args.sounds, wait=True)
